  `edad` varchar(100) DEFAULT NULL,
  `provincia_beneficiario` varchar(100) DEFAULT NULL,
  `departamento_beneficiario` varchar(100) DEFAULT NULL,
  `nacionalidad` varchar(100) DEFAULT NULL,
  `anio_tramite` int DEFAULT NULL,
  `mes_tramite` varchar(50) DEFAULT NULL,
  `tipo_tramite` varchar(255) DEFAULT NULL,
  `cantidad` int DEFAULT NULL,
  `fecha_proceso` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1963 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
