  `sede_atencion` varchar(150) DEFAULT NULL,
  `distrito_atencion` varchar(150) DEFAULT NULL,
  `provincia_atencion` varchar(150) DEFAULT NULL,
  `departamento_atencion` varchar(150) DEFAULT NULL,
  `calidad_migratoria` varchar(150) DEFAULT NULL,
  `tipo_tramite` varchar(150) DEFAULT NULL,
  `sexo` varchar(30) DEFAULT NULL,
  `edad` varchar(50) DEFAULT NULL,
  `nacionalidad` varchar(150) DEFAULT NULL,
  `estado_civil` varchar(100) DEFAULT NULL,
  `provincia_beneficiario` varchar(150) DEFAULT NULL,
  `departamento_beneficiario` varchar(150) DEFAULT NULL,
  `anio_tramite` int DEFAULT NULL,
  `mes_tramite` varchar(50) DEFAULT NULL,
  `cantidad` int DEFAULT NULL,
  `fecha_proceso` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12286 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
