DROP TABLE IF EXISTS `solicitud_calidad_migratoria`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `solicitud_calidad_migratoria` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sede_atencion` varchar(100) DEFAULT NULL,
  `distrito_atencion` varchar(100) DEFAULT NULL,
  `provincia_atencion` varchar(100) DEFAULT NULL,
  `departamento_atencion` varchar(100) DEFAULT NULL,
  `calidad_migratoria` varchar(255) DEFAULT NULL,
  `sexo` varchar(50) DEFAULT NULL,
  `edad` varchar(100) DEFAULT NULL,
  `nacionalidad` varchar(100) DEFAULT NULL,
  `estado_civil` varchar(100) DEFAULT NULL,
  `anio_tramite` int DEFAULT NULL,
  `mes_tramite` varchar(50) DEFAULT NULL,
  `cantidad` int DEFAULT NULL,
  `fecha_proceso` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4415 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
